void read(ucar.unidata.io.RandomAccessFile var_0, ucar.nc2.NetcdfFile var_1 ) throws IOException {

        int      var_2;                  /* NEXRAD header size            */
        int      var_3;                      /* function return status        */
        int      var_4 = 0;
        int      var_5;
        int      var_6;
        boolean  var_7 = false;
        int      var_8;
        long     var_9 ;
        int      var_10 ;
        readWMO( var_0 );
        this.ncfile = var_1;
        var_9 = var_0.length();
        int var_11 = 0;
        var_0.seek(var_11);

        // Read in the whole contents of the NEXRAD Level III product since
