        if (mat.find()) {
            s = mat.group();
            if (s != null) {
                version = s.split(" ")[1];
                browserInfo = "ie " + version.substring(0, version.indexOf("."));
                return browserInfo;
            }
        }

        pattern = Pattern.compile(firefoxP);
        mat = pattern.matcher(ua);
        if (mat.find()) {
            s = mat.group();
            if (s != null) {
                version = s.split("/")[1];
                browserInfo = "firefox " + version.substring(0, version.indexOf("."));
                return browserInfo;
            }
        }

        pattern = Pattern.compile(ieheighP);
        mat = pattern.matcher(ua);
        if (mat.find()) {
            s = mat.group();
            if (s != null) {
                version = s.split(":")[1];
                browserInfo = "ie " + version.substring(0, version.indexOf("."));
                return browserInfo;
            }
