			sleeProfileClassCodeGenerator.process(component);
			profileTableFramework.loadProfileTables(component);
		} catch (DeploymentException de) {
			throw de;
		} catch (Throwable t) {
		  t.printStackTrace();
			throw new SLEEException(t.getMessage(),t);
