                            i += 2;
                            break compare;
                        case '6':
                            buf.append('&');
                            i += 2;
                            break compare;
                        case '7':
                            buf.append('\'');
                            i += 2;
                            break compare;
                        case 'f':
                            buf.append('/');
                            i += 2;
                            break compare;
                        }
                    } else if (c2 == '3') {
                        switch (c3) {
                        case 'a':
                            buf.append(':');
                            i += 2;
                            break compare;
                        case 'c':
                            buf.append('<');
                            i += 2;
                            break compare;
                        case 'e':
                            buf.append('>');
                            i += 2;
                            break compare;
                        }
                    } else if (c2 == '4') {
