			ancestorForms = this.searchAndConvertHitsToFormWithAllFields(
					QueryBuilders.queryStringQuery(ancestorQuery.toString()),
					Index.DOCUMENT,
					DEFAULT_OFFSET,
					1,
					new Long[]{});
		}
		else
		{
			ancestorForms = this.searchAndConvertHitsToFormWithNoFields(
					QueryBuilders.queryStringQuery(ancestorQuery.toString()),
					Index.DOCUMENT,
					DEFAULT_OFFSET,
					1,
					new Long[]{});
		}

		Form returnVal = null;
