public double juday(int M, int D, int Y) {
    double JD;

    double IY = Y - (12 - M) / 10;
    double IM = M + 1 + 12 * ((12 - M) / 10);
    double I = IY / 100;
    double J = 2 - I + I / 4 + Math.round(365.25 * IY)
            + Math.round(30.6001 * IM);
    JD = (J + D + 1720994.50);
    return JD;
  }

