            for (AttachmentVo attachmentVo : emailVo.getAttachmentVos()) {
                File attachment = attachmentVo.getAttachment();


                if (attachment == null) {
                    InputStream inputStream = attachmentVo.getAttachmentInputStream();

                    if (attachmentVo.getAttachmentName() == null) {
